    const updateView = () => {
        allPages.forEach(p => { p.style.display = 'none'; p.classList.remove('active'); });

        if (isUserView) {
            if (userProfilePage) {
                userProfilePage.style.display = 'block';
                userProfilePage.classList.add('active');
            }
            switchBtn.style.visibility = 'hidden';
            userBtn.textContent = mainPageConfig[mainViewIndex].name;
        } else {
            const currentPage = mainPages[mainViewIndex];
            if (currentPage) {
                currentPage.style.display = 'block';
                currentPage.classList.add('active');
            }
            switchBtn.style.visibility = 'visible';
            switchBtn.textContent = mainPageConfig[mainViewIndex].name;
            userBtn.textContent = '个人档案';
        }
    };

    if (userBtn) {
        userBtn.addEventListener('click', () => {
            isUserView = !isUserView;
            updateView();
        });
    }

    if (switchBtn) {
        switchBtn.addEventListener('click', () => {
            mainViewIndex = (mainViewIndex + 1) % mainPageConfig.length;
            updateView();
        });
    }

    updateView();

    // --- Action Sending Logic ---
    const sendAction = (message) => {
        if (!message || typeof message !== 'string' || message.trim() === '') return;
        if (typeof triggerSlash === 'function') {
            triggerSlash(`/send ${message.trim()}|/trigger`);
        } else {
            console.log('Action Triggered (Dev Mode):', message.trim());
        }
    };

    const customInput = container.querySelector('#custom-action-input');
    const sendBtn = container.querySelector('#custom-action-send');
    if (sendBtn && customInput) {
        const triggerCustomSend = () => {
            const value = customInput.value;
