                triggerCustomSend();
            }
        });
    }

    container.addEventListener('click', function(event) {
        const actionElement = event.target.closest('.app-icon, .action-card');
        if (actionElement) {
            const action = actionElement.getAttribute('data-action');
            sendAction(action);
        }
    });
})();
</script>

</body>
</html>
