(function() {
    const scriptTag = document.currentScript;
    if (!scriptTag) return;
    const uiShell = scriptTag.previousElementSibling.previousElementSibling;
    if (!uiShell || uiShell.id !== 'terminal-shell') return;
    const container = uiShell.querySelector('#content-wrapper');
    if (!container) return;

    // --- Music Player Logic ---
    const musicToggleButton = container.querySelector('#music-toggle-btn');
    const audioPlayer = container.querySelector('#background-music');

    if (musicToggleButton && audioPlayer) {
        musicToggleButton.addEventListener('click', () => {
            if (audioPlayer.paused) {
                audioPlayer.play().catch(error => {
                    console.error("音乐播放失败:", error);
                });
                musicToggleButton.textContent = '⏸️ 暂停音乐';
            } else {
                audioPlayer.pause();
                musicToggleButton.textContent = '▶️';
            }
        });
    }

    // --- View Switching Logic ---
    let isUserView = false;
    let mainViewIndex = 0;

    const userBtn = container.querySelector('#user-btn');
    const switchBtn = container.querySelector('#switch-btn');
    const allPages = container.querySelectorAll('.page');
    const userProfilePage = container.querySelector('.page[data-section="user-profile"]');

    const mainPageConfig = [
        { id: 'main-control', name: '主控面板' },
        { id: 'action-choice', name: '行动选项' },
        { id: 'log', name: '系统日志' }
    ];
    const mainPages = mainPageConfig.map(config => container.querySelector(`.page[data-section="${config.id}"]`));

    const updateView = () => {
        allPages.forEach(p => { p.style.display = 'none'; p.classList.remove('active'); });

        if (isUserView) {
            if (userProfilePage) {
                userProfilePage.style.display = 'block';
                userProfilePage.classList.add('active');
            }
            switchBtn.style.visibility = 'hidden';
            userBtn.textContent = mainPageConfig[mainViewIndex].name;
        } else {
            const currentPage = mainPages[mainViewIndex];
            if (currentPage) {
                currentPage.style.display = 'block';
                currentPage.classList.add('active');
            }
            switchBtn.style.visibility = 'visible';
            switchBtn.textContent = mainPageConfig[mainViewIndex].name;
            userBtn.textContent = '个人档案';
        }
    };

    if (userBtn) {
        userBtn.addEventListener('click', () => {
            isUserView = !isUserView;
            updateView();
        });
    }

    if (switchBtn) {
        switchBtn.addEventListener('click', () => {
            mainViewIndex = (mainViewIndex + 1) % mainPageConfig.length;
            updateView();
        });
    }

    updateView();

    // --- Action Sending Logic ---
    const sendAction = (message) => {
        if (!message || typeof message !== 'string' || message.trim() === '') return;
        if (typeof triggerSlash === 'function') {
            triggerSlash(`/send ${message.trim()}|/trigger`);
        } else {
            console.log('Action Triggered (Dev Mode):', message.trim());
        }
    };

    const customInput = container.querySelector('#custom-action-input');
    const sendBtn = container.querySelector('#custom-action-send');
    if (sendBtn && customInput) {
        const triggerCustomSend = () => {
            const value = customInput.value;
            sendAction(value);
            customInput.value = '';
        };
        sendBtn.addEventListener('click', triggerCustomSend);
        customInput.addEventListener('keydown', (event) => {
            if (event.key === 'Enter' && !event.shiftKey) {
                event.preventDefault();
                triggerCustomSend();
            }
        });
    }

    container.addEventListener('click', function(event) {
        const actionElement = event.target.closest('.app-icon, .action-card');
        if (actionElement) {
            const action = actionElement.getAttribute('data-action');
            sendAction(action);
        }
    });
