            triggerSlash(`/send ${message.trim()}|/trigger`);
        } else {
            console.log('Action Triggered (Dev Mode):', message.trim());
        }
    };

    const customInput = container.querySelector('#custom-action-input');
    const sendBtn = container.querySelector('#custom-action-send');
    if (sendBtn && customInput) {
        const triggerCustomSend = () => {
            const value = customInput.value;
            sendAction(value);
            customInput.value = '';
        };
        sendBtn.addEventListener('click', triggerCustomSend);
        customInput.addEventListener('keydown', (event) => {
            if (event.key === 'Enter' && !event.shiftKey) {
                event.preventDefault();
                triggerCustomSend();
            }
        });
    }

    container.addEventListener('click', function(event) {
        const actionElement = event.target.closest('.app-icon, .action-card');
        if (actionElement) {
            const action = actionElement.getAttribute('data-action');
            sendAction(action);
        }
    });
})();
</script>

</body>
</html>
```

