entries.content:
{
  "region_profile": {
    "name": "夜帷村 (Yotobari Village)",
    "historical_context": "坐落于东京都自治州西部山区深处，一个在联邦地图上几乎没有标记的村落。由于其独特的地理位置和历史原因，'大和解'的浪潮几乎没有触及这里。村庄表面上保留着古老而淳朴的农耕传统，村民们和善好客，遵循着古老的节气与祭祀仪式，但在这份祥和之下，隐藏着一个与之截然相反、为维系村庄'繁荣'而存在的秘密风俗。",
    "village_emblem": {
      "totem": "白蛇",
      "sacred_plant": "垂枝樱",
      "logo": "无现代标志。村口的神社鸟居上悬挂着一个用稻草编织的交媾蛇形注连绳，象征着丰产与繁殖。"
    }
  },
  "geography_and_layout": {
    "location": "被三面环山，一面临湖的地形所包围，只有一条穿过茂密森林的崎岖山路与外界相连。村庄的名字'夜帷'，意指这里日照时间短，下午很早就被山影笼罩，如同拉上了夜晚的帷幕。",
    "layout": "村庄以湖边的'白蛇神社'为中心呈扇形展开。数十户传统的木结构房屋散落在山脚与湖岸之间，被大片的梯田和茶园所环绕。村中有一处天然温泉，是村民们重要的社交与休憩场所。",
    "key_locations": [
      {
        "name": "白蛇神社",
        "description": "供奉着村庄的守护神'白蛇大明神'的神社。传说白蛇神喜好祭品与欢愉，能为村庄带来丰收和子嗣。神社的现任巫女是村长的女儿'神凪'家代代相传的职位，村中所有重要的祭典都在此举行。",
        "atmosphere": "神圣、静谧、弥漫着一股甜腻的线香气味、情色"
      },
      {
        "name": "村长宅邸",
        "description": "村里规模最大、最气派的宅邸，是村长'神凪（Kannagi）'一家的住所。村长不仅是行政上的首领，也是村中秘密风俗的最高守护者和裁决者。",
        "atmosphere": "权威、传统、压抑、深不可测"
      },
      {
        "name": "公共温泉'蛇之汤'",
        "description": "从山中引流而下的天然温泉，设有男女混浴的露天浴池。这里是村民们放松身体、交流信息的场所，也是村庄特殊风俗实践的重要地点之一。温泉水汽缭绕，充满了硫磺和身体交融的气息。",
        "atmosphere": "开放、暧昧、慵懒、社交中心"
      },
      {
        "name": "旅馆'雏菊亭'",
        "description": "村里唯一一家接待外来者的旅馆，由一位名叫'菊乃'的温婉老板娘经营。旅馆的房间不多，但布置得非常雅致，提供精致的乡土料理。这里是外来者观察和融入村庄的第一个窗口，也是秘密的发生地。",
        "atmosphere": "好客、温馨、隐藏着秘密、充满诱惑"
      }
    ]
  },
  "culture_and_lifestyle": {
    "social_structure": {
      "general": "一个基于'献奉'与'恩惠'构建的社会。村民们相信，村庄的和平与丰收来自于向神明和'稀人'（Marebito，偶尔到访的外来者）的献奉。村长和巫女拥有绝对的权威，负责解释神谕和主持仪式。村民则以家族为单位，共同遵守并执行村中的规定。",
      "interpersonal": "村民对外表现得极为热情好客，尤其是对男性外来者，会给予无微不至的照顾。但在这种热情的背后，是一种审视和评估的态度。村内的女性地位看似低下，实则在'献奉'体系中扮演着不可或缺的关键角色。"
    },
    "belief_and_customs": {
      "worldview": "村民们信仰一种混合了神道教和原始泛灵论的独特信仰。他们认为性力（生命力）是世界运转的根本能源，通过献身和交媾，可以将这份能量奉献给神明，从而换取村庄的繁荣。对于外界的现代科技和价值观，他们表面上好奇，内心则认为那是'无根的'、'干涸的'。",
      "rituals": {
        "name": "神婚祭 (Kamimukae Matsuri)",
        "description": "每年夏末举行的最重要祭典。祭典期间，村子会挑选一名健壮的、初次到访的年轻男性作为'神婿'，代表神明与村中未婚的女性们交合，以此祈求来年的丰收和子嗣满堂。村中的已婚女性也会在这期间为'神婿'提供'奉侍'，以分享'神恩'。",
        "process": "祭典分为多个阶段，包括欢迎'神婿'的宴会、巫女的祈福舞蹈、以及在神社或特定场所进行的持续数日的'结合仪式'。"
      },
      "taboos": "禁止村中女性与外来者产生真正的'恋情'；禁止泄露村中风俗给外界；禁止在非祭典期间拒绝'稀人'的求欢。违背禁忌者，将由村长和长老会进行严厉的惩罚。"
    },
    "economy_and_life": {
      "livelihood": "以种植高品质的茶叶和水稻为主，辅以湖中的渔业。由于风俗带来的高生育率，村庄从不缺乏劳动力。村庄会将一部分特产通过隐秘的渠道售卖到外界，换取必要的物资和金钱。",
      "diet": "饮食精致，擅长利用山野的各种食材。湖鱼、山野菜、自家酿造的浊酒是餐桌上的常客。食物中常常会添加一些具有催情效果的草药，被认为是神明的恩赐。"
    },
    "gender_dynamics": {
      "women": {
        "social_role": "女性被视为'神的容器'和'丰饶的土地'。她们从小就接受'献身是荣耀'的教育，学习取悦男性的技巧。巫女是所有女性的领袖和榜样。她们的身体不完全属于自己，而是属于整个村庄和神明。已婚女性在'神婚祭'之外，也有义务'款待'偶然到访的'稀人'。",
        "sexuality": "女性的性欲被认为是神圣的，是与神明沟通的渠道，因此不被压抑，反而受到鼓励。她们在性事上主动、开放，并以此为荣。一个能让'神婿'或'稀人'满意的女性会获得很高的声望。",
        "life_path": "生下子嗣，特别是男孩，是她们最重要的任务。无法生育的女性会被认为'不受神明眷顾'，地位低下。她们在村庄内部的通婚是被允许的，但核心的血脉延续依赖于'神婿'和'稀人'这些外来者。"
      },
      "men": {
        "social_role": "村中的男性主要负责农耕、渔猎和村庄的防卫。他们是家庭的维持者，也是风俗的执行者。他们将自己的妻子或女儿献给'神婿'视为荣耀，认为这是为村庄做贡献。对于因此而出生的孩子，他们会视如己出，共同抚养。",
        "masculinity_and_jealousy": "嫉妒被认为是'小气'和'对神不敬'的表现。男性的价值体现在他的劳作能力和对村庄规则的遵从程度上。虽然他们也享有村中女性的'奉侍'，但最优质的、最神圣的'献奉'是留给外来者的。",
        "social_life": "男人们的社交围绕着劳作和村中的小型宴会。他们会一起喝酒、讨论农事，并为即将到来的'神婚祭'能挑选到一位强壮的'神婿'而感到兴奋。"
      }
    }
  }
}

